import{_ as s,l as p,o as e,c as i,v as r,p as l,x as o,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Paxos","description":"","frontmatter":{"title":"Paxos","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/paxos.md","filePath":"cs/paxos.md","lastUpdated":1789023840000}'),m={name:"cs/paxos.md"};function h(E,a,P,x,_,A){const t=p("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="paxos" tabindex="-1">Paxos <a class="header-anchor" href="#paxos" aria-label="Permalink to &quot;Paxos&quot;">​</a></h1><div class="epigraph"><p>两阶段：先争一个提案编号的承诺，再对那个编号接受值。多数派相交让两个被选中的值不能不同。活性不保证——FLP 允许。</p><footer>—— 据 Lamport, The Part-Time Parliament, TOCS 1998；Paxos Made Simple, 2001 整理</footer></div><p>上一课<a href="/cs/replicated-state-machine">复制状态机</a>要一条全序日志。缺口是<strong>单槽共识</strong>：多数崩溃停进程如何对「这个 index 写什么」达成一致。本课钉 Basic Paxos，不把 Multi-Paxos 的稳定领导者写完。后课默认：prepare/accept、承诺、多数派这些词已经钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提议者选编号 \\(n\\)，向接受者发 prepare。若 \\(n\\) 大于该接受者已承诺的编号，则承诺忽略更小者，并返回已接受的最高值。提议者若收到多数派回复：若有人带过值，必须提议其中编号最高的那个；否则可提议自己的值。然后 accept。若多数派接受，该值被选定。</p><p>缺口：为何安全。任意两个多数派相交，后一次 prepare 会看见前一次已接受的值并被迫跟着走，于是不能选定第二个不同值。与<a href="/cs/quorum-rw">quorum 寄存器</a>同构在相交，对象是「这个槽的值」而不是客户端 blob。</p><p><span class="marginnote">TOCS 1998 用议会寓言；2001 短文去掉寓言。编号必须全局唯一且单调，常用 <code>(计数, 节点 id)</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>角色可重叠：每节点提议者+接受者+学习者。学习者靠 accept 广播或向多数派查询。冲突：两个提议者交错 prepare，可能活锁——这是活性，不是安全洞。编号加一重试。</p>',9)),(e(),l(c,null,{default:o(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22prepare%20n%22%5D%20--%3E%20PROM%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%89%BF%E8%AF%BA%22%5D%0A%20%20PROM%20--%3E%20VAL%5B%22%E9%80%89%E5%80%BC%3A%20%E5%B7%B2%E6%8E%A5%E5%8F%97%E7%9A%84%E6%9C%80%E9%AB%98%20%2F%20%E8%87%AA%E5%A4%87%22%5D%0A%20%20VAL%20--%3E%20ACC%5B%22accept%22%5D%0A%20%20ACC%20--%3E%20CHOSEN%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%8E%A5%E5%8F%97%20%E2%87%92%20%E9%80%89%E5%AE%9A%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>信道可丢消息、可延迟；崩溃恢复必须把承诺编号与已接受值写进稳定存储，否则<a href="/cs/failure-models">崩溃恢复</a>会改口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FLP：纯异步下可能永远活锁或永远选不出。实践加随机退避与「尽量一个提议者」。安全证明不依赖超时。部分同步下超时让某个提议者的 \\(n\\) 跑在前面，于是终止。</p><p>单槽只决定一个值。状态机需要槽序列——下一课。不要把 2PC 的协调者当 Paxos：2PC 阻塞在协调者崩溃，Paxos 换提议者。后课专门对照。</p><p>本课不写拜占庭 Paxos。口头撒谎会分裂多数派观察，Lamport 的原版假定非拜占庭。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写磁盘布局、不引入联合多数派（membership）。不把 ZooKeeper 当 Paxos 实现细节。后课默认：一个值的安全 = 编号承诺 + 多数派相交；活 = 终有一个提议者独占足够久。Multi-Paxos 把独占做成领导者任期。</p><p>相交保证至多一个值；prepare 的「跟着已有值走」保证一旦有值就不能换。两句话就是安全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Prepare 争承诺，accept 写值；多数派相交保唯一。</li><li>已接受值必须被更高编号带着走。</li><li>安全异步成立；终止靠部分同步与反活锁。</li><li>出处：Lamport, TOCS 1998；<em>Paxos Made Simple</em>, 2001。</li></ul>',10))])}const B=s(m,[["render",h]]);export{f as __pageData,B as default};
